using System;
using System.IO;
using System.Linq;
using System.Text;
using TMPro;
using UnityEditor;
using UnityEditor.Build.Reporting;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;
public static class GridShiftV11Audit {
 public static void Batch(){var log=new StringBuilder();bool ok=true;void Check(bool condition,string message){log.AppendLine((condition?"PASS ":"FAIL ")+message);ok&=condition;}Check(!File.ReadAllText("Packages/manifest.json").Contains("dev.voltstro"),"manifest sem dependências UWB/CEF");foreach(var path in new[]{"Assets/Scenes/MainMenu.unity","Assets/Scenes/SampleScene.unity","Assets/Scenes/Office.unity"}){var scene=EditorSceneManager.OpenScene(path);int missing=0,legacy=0;foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true)){missing+=GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject);foreach(var m in t.GetComponents<MonoBehaviour>())if(m!=null&&((m.GetType().Namespace??"").StartsWith("VoltstroStudios")||m.GetType().Name.StartsWith("GridShiftUwb")))legacy++;}Check(missing==0&&legacy==0,path+": sem scripts ausentes ou componentes antigos");var routes=Object.FindObjectsByType<TrafficRoute>(FindObjectsInactive.Include,FindObjectsSortMode.None);Check(routes.Select(GridShiftRouteIdentity.Of).Distinct().Count()==routes.Length,path+": IDs de rotas únicos");Check(Object.FindObjectsByType<TMP_Text>(FindObjectsInactive.Include,FindObjectsSortMode.None).All(t=>t.text.IndexOf("DEMO",StringComparison.OrdinalIgnoreCase)<0),path+": sem rótulos DEMO");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}
 var dependencies=AssetDatabase.GetDependencies(new[]{"Assets/Scenes/MainMenu.unity","Assets/Scenes/SampleScene.unity","Assets/Scenes/Office.unity","Assets/Generated/Experience5/TabletViewModel.prefab"},true);Check(!dependencies.Any(p=>p.Contains("voltstro")||p.Contains("PortableBrowser")||p.Contains("Generated/Terminal/")),"cenas e tablet sem dependências de navegador");GridShiftProfiles.RootOverride=Path.GetFullPath("Temp/AuditProfiles-"+Guid.NewGuid().ToString("N"));GridShiftProfiles.Login("auditoria@local","descartada",out _);var legacyPath=Path.GetFullPath("Temp/legacy-v1-audit.json");File.WriteAllText(legacyPath,"{\"version\":1,\"money\":42,\"clock\":720,\"orders\":[],\"playerPosition\":{\"x\":230,\"y\":-4,\"z\":230},\"playerRotation\":{\"x\":0,\"y\":0,\"z\":0,\"w\":1}}");bool readable=DeliverySaveStore.ReadAt(legacyPath,out var old,out _);Check(readable,"JSON v1 real, sem campos novos, continua legível");if(readable){old.version=3;old.profileId=GridShiftProfiles.ProfileId;old.slot=5;old.companyName="Partida importada";Check(DeliverySaveStore.WriteAt(GridShiftProfiles.SlotPath(5),old)&&GridShiftProfiles.Read(5,out _,out _),"conversão do formato antigo para slot v3 válido");}log.AppendLine("RESULT "+(ok?"SUCCESS":"FAILURE"));Directory.CreateDirectory("Docs/Validacao11");File.WriteAllText("Docs/Validacao11/audit.txt",log.ToString());EditorApplication.Exit(ok?0:1);}
 public static void Build(){Directory.CreateDirectory("Build11");var result=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=EditorBuildSettings.scenes.Where(s=>s.enabled).Select(s=>s.path).ToArray(),locationPathName="Build11/GridShift.exe",target=BuildTarget.StandaloneWindows64,options=BuildOptions.Development});bool clean=!Directory.GetFiles("Build11","*",SearchOption.AllDirectories).Any(p=>Path.GetFileName(p).IndexOf("libcef",StringComparison.OrdinalIgnoreCase)>=0||Path.GetFileName(p).IndexOf("unitywebbrowser",StringComparison.OrdinalIgnoreCase)>=0);File.WriteAllText("Docs/Validacao11/build.txt","Build: "+result.summary.result+"\nErrors: "+result.summary.totalErrors+"\nBytes: "+result.summary.totalSize+"\nCEF/UWB binaries absent: "+clean+"\n");EditorApplication.Exit(result.summary.result==BuildResult.Succeeded&&clean?0:1);}
}
